/-- A closed axis-aligned box in the two-dimensional score space. -/
-- @node: causalHardScoreBox
def causalHardScoreBox (a0 b0 a1 b1 : ℝ) : Set Score :=
  {z | a0 ≤ z 0 ∧ z 0 ≤ b0 ∧ a1 ≤ z 1 ∧ z 1 ≤ b1}

