/-- The common square support `[-3,3]²`. -/
def causalHardSquare : Set Score :=
  {x | ∀ i, (-3 : ℝ) ≤ x i ∧ x i ≤ 3}

/-- The disjoint hard cells and their common complement as a classifier. -/
-- @node: causalPackingPartitionSet
def causalPackingPartitionSet {M : ℕ} (centers : Fin M → Score) (w : ℝ) :
    Unit ⊕ Fin M → Set CausalObservation
  | .inr j => {z | causalScore z ∈ causalHardCell (centers j) w}
  | .inl _ => {z | causalScore z ∉ ⋃ j, causalHardCell (centers j) w}

/-- Coordinate-partial Lipschitz quotients of total order at most `p`. -/
def coordinatePartialLipschitzValues (f : Score → ℝ) (p : ℕ)
    (S : Set Score) : Set ℝ :=
  {r | ∃ alpha : Fin 2 → ℕ, coordinateMultiOrder alpha ≤ p ∧
    ∃ x ∈ S, ∃ z ∈ S, x ≠ z ∧
      r = |coordinatePartial f alpha x - coordinatePartial f alpha z| / ‖x - z‖}

/-- Absolute coordinate partials of total order at most `p` on `S`. -/
def coordinatePartialValues (f : Score → ℝ) (p : ℕ) (S : Set Score) : Set ℝ :=
  {r | ∃ alpha : Fin 2 → ℕ, coordinateMultiOrder alpha ≤ p ∧
    ∃ x ∈ S, r = |coordinatePartial f alpha x|}

/-- A component of the fixed hard-square population-Gram certificate. -/
-- @node: hardSquareSectorDomain
def hardSquareSectorDomain (h : ℝ) : Set (ℝ × ℝ) :=
  {q | 0 < q.1 ∧ 0 < q.2 ∧ planarRadius q ≤ h}

