/-- The half-disc cell cut out by the square at a boundary packing point. -/
def packingCell {M : ℕ} (centers : Fin M → Score) (w : ℝ) (j : Fin M) : Set Score :=
  Metric.closedBall (centers j) w ∩ packingSquare

/-- The packing cells together with their common complement form the finite
partition used to split the marked Poisson experiment. -/
-- @node: packingPartitionSet
def packingPartitionSet {M : ℕ} (centers : Fin M → Score) (w : ℝ) :
    Unit ⊕ Fin M → Set Observation
  | .inr j => {o | o.2 ∈ packingCell centers w j}
  | .inl _ => {o | o.2 ∉ ⋃ j, packingCell centers w j}

/-- The fixed unit square supporting every law in the hard family. -/
def packingSquare : Set Score :=
  scoreCube (1 / 2 : ℝ)

/-- The degree-`p` monomial basis `(1,u,…,u^p)`. -/
def polyBasis (p : ℕ) (u : ℝ) : Fin (p + 1) → ℝ :=
  fun k => u ^ (k : ℕ)

/-- The coordinate cube `[-r,r]²`, regarded as a subset of Euclidean space. -/
def scoreCube (r : ℝ) : Set Score :=
  {x | ∀ i, |x i| ≤ r}

